import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import '../index.css'; // <- corrected path

export default function Signup() {
  const [name, setName] = useState(''); // ✅ Added state for user name
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirm, setConfirm] = useState('');
  const [error, setError] = useState('');
  const navigate = useNavigate();

  function handleSubmit(e) {
    e.preventDefault();
    setError('');

    if (password !== confirm) {
      setError('Passwords do not match');
      return;
    }

    const usersJson = localStorage.getItem('users');
    const users = usersJson ? JSON.parse(usersJson) : [];

    if (users.find(u => u.email === email)) {
      setError('Email already registered.');
      return;
    }

    // ✅ Include name when saving user
    users.push({ name, email, password });
    localStorage.setItem('users', JSON.stringify(users));

    const token = btoa(email + ':' + Date.now());
    localStorage.setItem('authToken', token);
    localStorage.setItem('currentUser', JSON.stringify({ name, email }));

    // ✅ Always reset this flag on fresh signup
    localStorage.removeItem('profileCreated');

    alert("Signup successful!");
    navigate('/role-selection'); // ✅ Force navigation every time
  }

  return (
    <div className="auth-page">
      <div className="auth-container">
        <h1>SoftScale</h1>
        <form onSubmit={handleSubmit}>
          {/* ✅ New input for full name */}
          <input
            type="text"
            placeholder="Full Name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            required
          />

          <input
            type="email"
            placeholder="Email address"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
          />

          <input
            type="password"
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
          />

          <input
            type="password"
            placeholder="Confirm password"
            value={confirm}
            onChange={(e) => setConfirm(e.target.value)}
            required
          />

          {error && <div style={{ color: '#cc3b3b', marginTop: 8 }}>{error}</div>}

          <button type="submit">Create account</button>
        </form>
        <p>
          Already have an account? <Link to="/login">Login</Link>
        </p>
      </div>
    </div>
  );
}
